const blocks=[['05:00–05:30','Wake, hydrate, light movement'],['05:30–06:30','Exercise'],['06:30–07:00','Meal'],['07:00–09:00','Deep work block 1'],['09:00–09:15','Break'],['09:15–11:15','Deep work block 2'],['11:15–12:00','Review latest interview/report'],['12:00–13:00','Lunch / rest'],['13:00–15:00','Deep work block 3 · team/startup progress'],['15:00–15:30','Break'],['15:30–17:00','Community / team engagement'],['17:00–18:00','Wind-down movement'],['18:00–19:00','Dinner'],['19:00–20:00','Reflection + plan tomorrow · check-in'],['20:00–21:00','Personal time'],['21:00 onward','Wind down for sleep']];const required=14,key='discipline-os-'+new Date().toISOString().slice(0,10);let done=JSON.parse(localStorage.getItem(key)||'[]');const $=id=>document.getElementById(id);$('timezone').textContent=Intl.DateTimeFormat().resolvedOptions().timeZone;function render(){let count=done.filter(i=>i<required).length,pct=Math.round(count/required*100);$('progressText').innerHTML=`${count}<span>/14</span>`;$('pct').textContent=pct+'%';$('progressBar').style.width=pct+'%';$('ringProgress').style.strokeDashoffset=107-(107*pct/100);$('streak').textContent=localStorage.getItem('discipline-streak')||0;const now=new Date().getHours()*60+new Date().getMinutes();let current=-1;$('#timeline').innerHTML=blocks.map((b,i)=>{let start=parseInt(b[0]);if(current<0&&!done.includes(i)&&start<=now)current=i;let c=done.includes(i);return `<div class="block ${c?'completed':''} ${i===current?'current':''}"><div class="time">${b[0]}</div><div><div class="block-title">${b[1]}</div><div class="block-meta">${i<required?'Required block':'Protected time · optional'}</div></div><button class="check" data-i="${i}">✓</button></div>`}).join('');document.querySelectorAll('.check').forEach(x=>x.onclick=()=>{let i=+x.dataset.i;done=done.includes(i)?done.filter(n=>n!==i):[...done,i];localStorage.setItem(key,JSON.stringify(done));if(done.filter(i=>i<required).length===required)localStorage.setItem('discipline-streak','1');render()});let n=blocks.findIndex((_,i)=>!done.includes(i));$('#nextTitle').textContent=n<0?'Standard complete for today.':blocks[n][1];$('#nextMeta').textContent=n<0?'You kept the line. Protect tomorrow.':'Your next commitment in local time.';$('#nextTime').textContent=n<0?'COMPLETE':blocks[n][0]}$('#resetBtn').onclick=()=>{done=[];localStorage.setItem(key,'[]');render()};$('#themeBtn').onclick=()=>document.body.classList.toggle('light');if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');render();